cd /app && echo "=== lines whose timestamp date != filename date ==="; for f in logs/*.log; do fd=$(basename "$f" | cut -c1-10); awk -v d="$fd" 'substr($1,1,10)!=d{c++} END{if(c) print FILENAME": "c}' "$f"; done | head; echo "=== lines with >1 bracketed severity token ==="; grep -hEc '\[(ERROR|WARNING|INFO)\].*\[(ERROR|WARNING|INFO)\]' logs/*.log | awk '{s+=$1} END{print s+0}'; echo "=== bracket tokens not followed by space (malformed) ==="; grep -hoE '\[(ERROR|WARNING|INFO)\]' logs/*.log | sort | uniq -c; echo "=== indep boundary sums (filename-based, bracket token) ==="; python3 - <<'EOF'
import re,glob,os
from datetime import date,timedelta
cnt={}
for f in glob.glob('/app/logs/*.log'):
    d=os.path.basename(f)[:10]
    for line in open(f,errors='replace'):
        m=re.search(r'\[(ERROR|WARNING|INFO)\]',line)
        if m:
            cnt[(d,m.group(1))]=cnt.get((d,m.group(1)),0)+1
R=date(2025,8,12)
def s(a,b,k): 
    t=date.fromisoformat(a)
    return sum(v for (d,sev),v in cnt.items() if sev==k and t<=date.fromisoformat(d)<=b)
for name,a in [('today',R),('last_7_days',R-timedelta(6)),('last_30_days',R-timedelta(29)),('month_to_date',R.replace(day=1))]:
    print(name,[s(a.isoformat(),R.isoformat(),k) for k in ('ERROR','WARNING','INFO')])
print('total',[sum(v for (d,sev),v in cnt.items() if sev==k) for k in ('ERROR','WARNING','INFO')])
print('sum_by_sev_all_periods_should_match_total', sum(cnt.values()))
EOF
